#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <immintrin.h>
#include <omp.h>

typedef void (*kern_fn)(int kc, const float *restrict a, const float *restrict b,
                        float *restrict c, size_t ldc, int first);

#if defined(__AVX512F__)

#define ZDECL(r) __m512 z##r##0 = _mm512_setzero_ps(), z##r##1 = _mm512_setzero_ps();
#define ZROW(r) { __m512 av = _mm512_set1_ps(a[r]); \
    z##r##0 = _mm512_fmadd_ps(av, b0, z##r##0); \
    z##r##1 = _mm512_fmadd_ps(av, b1, z##r##1); }
#define ZST(r) { float *cr = c + (size_t)(r) * ldc; \
    _mm512_storeu_ps(cr, z##r##0); _mm512_storeu_ps(cr + 16, z##r##1); }
#define ZAD(r) { float *cr = c + (size_t)(r) * ldc; \
    _mm512_storeu_ps(cr, _mm512_add_ps(_mm512_loadu_ps(cr), z##r##0)); \
    _mm512_storeu_ps(cr + 16, _mm512_add_ps(_mm512_loadu_ps(cr + 16), z##r##1)); }
#define ZPF(r) { __builtin_prefetch(c + (size_t)(r) * ldc, 1, 3); \
    __builtin_prefetch(c + (size_t)(r) * ldc + 16, 1, 3); }

/* 12x32 tile: a is 12-wide k-major, b is 32-wide k-major. */
static void k512(int kc, const float *restrict a, const float *restrict b,
                 float *restrict c, size_t ldc, int first)
{
    ZDECL(0) ZDECL(1) ZDECL(2) ZDECL(3) ZDECL(4) ZDECL(5)
    ZDECL(6) ZDECL(7) ZDECL(8) ZDECL(9) ZDECL(10) ZDECL(11)
    ZPF(0) ZPF(1) ZPF(2) ZPF(3) ZPF(4) ZPF(5)
    ZPF(6) ZPF(7) ZPF(8) ZPF(9) ZPF(10) ZPF(11)

    #pragma GCC unroll 4
    for (int k = 0; k < kc; k++) {
        __m512 b0 = _mm512_loadu_ps(b);
        __m512 b1 = _mm512_loadu_ps(b + 16);
        ZROW(0) ZROW(1) ZROW(2) ZROW(3) ZROW(4) ZROW(5)
        ZROW(6) ZROW(7) ZROW(8) ZROW(9) ZROW(10) ZROW(11)
        a += 12;
        b += 32;
    }

    if (first) {
        ZST(0) ZST(1) ZST(2) ZST(3) ZST(4) ZST(5)
        ZST(6) ZST(7) ZST(8) ZST(9) ZST(10) ZST(11)
    } else {
        ZAD(0) ZAD(1) ZAD(2) ZAD(3) ZAD(4) ZAD(5)
        ZAD(6) ZAD(7) ZAD(8) ZAD(9) ZAD(10) ZAD(11)
    }
}

#endif

#if defined(__AVX2__) && defined(__FMA__)

#define YDECL(r) __m256 y##r##0 = _mm256_setzero_ps(), y##r##1 = _mm256_setzero_ps();
#define YROW(r) { __m256 av = _mm256_broadcast_ss(a + (r)); \
    y##r##0 = _mm256_fmadd_ps(av, b0, y##r##0); \
    y##r##1 = _mm256_fmadd_ps(av, b1, y##r##1); }
#define YST(r) { float *cr = c + (size_t)(r) * ldc; \
    _mm256_storeu_ps(cr, y##r##0); _mm256_storeu_ps(cr + 8, y##r##1); }
#define YAD(r) { float *cr = c + (size_t)(r) * ldc; \
    _mm256_storeu_ps(cr, _mm256_add_ps(_mm256_loadu_ps(cr), y##r##0)); \
    _mm256_storeu_ps(cr + 8, _mm256_add_ps(_mm256_loadu_ps(cr + 8), y##r##1)); }
#define YPF(r) { __builtin_prefetch(c + (size_t)(r) * ldc, 1, 3); \
    __builtin_prefetch(c + (size_t)(r) * ldc + 15, 1, 3); }

/* 6x16 tile: a is 6-wide k-major, b is 16-wide k-major. */
static void k256(int kc, const float *restrict a, const float *restrict b,
                 float *restrict c, size_t ldc, int first)
{
    YDECL(0) YDECL(1) YDECL(2) YDECL(3) YDECL(4) YDECL(5)
    YPF(0) YPF(1) YPF(2) YPF(3) YPF(4) YPF(5)

    #pragma GCC unroll 4
    for (int k = 0; k < kc; k++) {
        __m256 b0 = _mm256_loadu_ps(b);
        __m256 b1 = _mm256_loadu_ps(b + 8);
        YROW(0) YROW(1) YROW(2) YROW(3) YROW(4) YROW(5)
        a += 6;
        b += 16;
    }

    if (first) {
        YST(0) YST(1) YST(2) YST(3) YST(4) YST(5)
    } else {
        YAD(0) YAD(1) YAD(2) YAD(3) YAD(4) YAD(5)
    }
}

#endif

/* Portable 4x16 tile, used only when no AVX2/FMA is available. */
static void kgen(int kc, const float *restrict a, const float *restrict b,
                 float *restrict c, size_t ldc, int first)
{
    float acc[4][16];
    memset(acc, 0, sizeof acc);
    for (int k = 0; k < kc; k++)
        for (int r = 0; r < 4; r++)
            for (int j = 0; j < 16; j++)
                acc[r][j] += a[k * 4 + r] * b[k * 16 + j];
    for (int r = 0; r < 4; r++) {
        float *cr = c + (size_t)r * ldc;
        if (first)
            for (int j = 0; j < 16; j++) cr[j] = acc[r][j];
        else
            for (int j = 0; j < 16; j++) cr[j] += acc[r][j];
    }
}

typedef struct {
    kern_fn f;
    int mr, nr, kc, mb, nt;
} cand_t;

#define MAXC 4
#define MAXMR 12
#define MAXNR 32

static cand_t g_cand[MAXC];
static int g_ncand = 0;

static float *g_a = NULL, *g_b = NULL;
static size_t g_acap = 0, g_bcap = 0;

static float *grow(float **p, size_t *cap, size_t need)
{
    need = (need + 63) & ~(size_t)63;
    if (need > *cap) {
        free(*p);
        *p = (float *)aligned_alloc(64, need);
        *cap = need;
    }
    return *p;
}

static long read_long(const char *path)
{
    FILE *f = fopen(path, "r");
    if (!f) return -2;
    long a = -1;
    if (fscanf(f, "%ld", &a) != 1) a = -1;
    fclose(f);
    return a;
}

/* Thread counts: *cap = one per physical core, *all = every logical CPU.
   Both respect the cgroup CPU quota and an explicit OMP_NUM_THREADS. */
static void pick_threads(int *cap, int *all)
{
    int nt = omp_get_max_threads();
    if (getenv("OMP_NUM_THREADS")) { *cap = *all = nt; return; }

    int quota = 0;
    FILE *f = fopen("/sys/fs/cgroup/cpu.max", "r");
    if (f) {
        char buf[64];
        long per = 0;
        if (fscanf(f, "%63s %ld", buf, &per) == 2 && strcmp(buf, "max") != 0) {
            long q = atol(buf);
            if (q > 0 && per > 0) quota = (int)((q + per - 1) / per);
        }
        fclose(f);
    } else {
        long q = read_long("/sys/fs/cgroup/cpu/cpu.cfs_quota_us");
        long per = read_long("/sys/fs/cgroup/cpu/cpu.cfs_period_us");
        if (q > 0 && per > 0) quota = (int)((q + per - 1) / per);
    }

    int smt = 1;
    f = fopen("/sys/devices/system/cpu/cpu0/topology/thread_siblings_list", "r");
    if (f) {
        char buf[128];
        if (fgets(buf, sizeof buf, f)) {
            int cnt = 1;
            for (char *p = buf; *p; p++)
                if (*p == ',') cnt++;
            if (cnt == 1 && strchr(buf, '-')) cnt = 2;
            smt = cnt;
        }
        fclose(f);
    }

    int procs = omp_get_num_procs();
    int phys = smt > 1 ? procs / smt : procs;
    if (phys < 1) phys = 1;

    int a = nt;
    if (quota > 0 && a > quota) a = quota;
    if (a < 1) a = 1;
    int c = a < phys ? a : phys;
    if (c < 1) c = 1;
    *cap = c;
    *all = a;
}

static void add_cand(kern_fn f, int mr, int nr, int kc, int nt)
{
    if (g_ncand >= MAXC) return;
    cand_t *c = &g_cand[g_ncand++];
    c->f = f; c->mr = mr; c->nr = nr; c->kc = kc; c->mb = mr * 8; c->nt = nt;
}

static void init_cands(void)
{
    int cap, all;
    pick_threads(&cap, &all);
#if defined(__AVX512F__)
    add_cand(k512, 12, 32, 192, cap);
    if (all != cap) add_cand(k512, 12, 32, 192, all);
    add_cand(k256, 6, 16, 384, cap);
    if (all != cap) add_cand(k256, 6, 16, 384, all);
    else add_cand(k512, 12, 32, 256, cap);
#elif defined(__AVX2__) && defined(__FMA__)
    add_cand(k256, 6, 16, 384, cap);
    if (all != cap) add_cand(k256, 6, 16, 384, all);
    add_cand(k256, 6, 16, 256, cap);
    if (all != cap) add_cand(k256, 6, 16, 256, all);
#else
    add_cand(kgen, 4, 16, 256, cap);
    if (all != cap) add_cand(kgen, 4, 16, 256, all);
#endif
}

/* B panel p: columns [p*NR, p*NR+NR), all k, k-major, zero padded. */
static void pack_b_panel(const float *B, int n, int p, int NR, float *dst)
{
    int j0 = p * NR;
    int w = n - j0 < NR ? n - j0 : NR;
    const float *src = B + j0;
    if (w == NR) {
        for (int k = 0; k < n; k++) {
            memcpy(dst, src, (size_t)NR * sizeof(float));
            src += n;
            dst += NR;
        }
    } else {
        for (int k = 0; k < n; k++) {
            int j = 0;
            for (; j < w; j++) dst[j] = src[j];
            for (; j < NR; j++) dst[j] = 0.0f;
            src += n;
            dst += NR;
        }
    }
}

/* A strip starting at row i0: MR rows, all k, k-major, zero padded.
   Reads 16 consecutive k per row; the scattered writes stay in L1. */
static void pack_a_strip(const float *A, int n, int i0, int MR, float *d)
{
    int h = n - i0 < MR ? n - i0 : MR;
    for (int k0 = 0; k0 < n; k0 += 16) {
        int kk = n - k0 < 16 ? n - k0 : 16;
        float *dd = d + (size_t)k0 * MR;
        for (int r = 0; r < MR; r++) {
            if (r < h) {
                const float *src = A + (size_t)(i0 + r) * n + k0;
                for (int q = 0; q < kk; q++) dd[q * MR + r] = src[q];
            } else {
                for (int q = 0; q < kk; q++) dd[q * MR + r] = 0.0f;
            }
        }
    }
}

static void run(const float *A, const float *B, float *C, int n, const cand_t *cf)
{
    const int MR = cf->mr, NR = cf->nr, MB = cf->mb, nt = cf->nt;
    kern_fn kern = cf->f;

    int nstrips = (n + MR - 1) / MR;
    int npanels = (n + NR - 1) / NR;
    float *Ap = grow(&g_a, &g_acap, (size_t)nstrips * MR * n * sizeof(float));
    float *Bp = grow(&g_b, &g_bcap, (size_t)npanels * NR * n * sizeof(float));

    int nk = (n + cf->kc - 1) / cf->kc;
    int kcb = (n + nk - 1) / nk;

    int mblocks = (n + MB - 1) / MB;
    int nb = NR * 4 > 128 ? NR * 4 : 128;
    while (nb > 2 * NR && mblocks * ((n + nb - 1) / nb) < 4 * nt) nb /= 2;
    int nblocks = (n + nb - 1) / nb;
    int ntasks = mblocks * nblocks;
    int npack = nstrips + npanels;

    #pragma omp parallel num_threads(nt)
    {
        #pragma omp for schedule(dynamic, 4)
        for (int it = 0; it < npack; it++) {
            if (it < npanels)
                pack_b_panel(B, n, it, NR, Bp + (size_t)it * n * NR);
            else {
                int s = it - npanels;
                pack_a_strip(A, n, s * MR, MR, Ap + (size_t)s * n * MR);
            }
        }

        #pragma omp for schedule(dynamic, 1)
        for (int t = 0; t < ntasks; t++) {
            int ib = t / nblocks, jb = t % nblocks;
            int i0 = ib * MB;
            int iend = i0 + MB < n ? i0 + MB : n;
            int jstart = jb * nb;
            int jend = jstart + nb < n ? jstart + nb : n;

            for (int k0 = 0; k0 < n; k0 += kcb) {
                int kc = n - k0 < kcb ? n - k0 : kcb;
                int first = (k0 == 0);
                for (int j = jstart; j < jend; j += NR) {
                    const float *bp = Bp + (size_t)(j / NR) * n * NR + (size_t)k0 * NR;
                    int nr = n - j < NR ? n - j : NR;
                    for (int i = i0; i < iend; i += MR) {
                        const float *ap = Ap + (size_t)(i / MR) * n * MR + (size_t)k0 * MR;
                        int mr = n - i < MR ? n - i : MR;
                        float *cp = C + (size_t)i * n + j;
                        if (mr == MR && nr == NR) {
                            kern(kc, ap, bp, cp, (size_t)n, first);
                        } else {
                            float tmp[MAXMR * MAXNR] __attribute__((aligned(64)));
                            kern(kc, ap, bp, tmp, (size_t)NR, 1);
                            for (int r = 0; r < mr; r++) {
                                float *cr = cp + (size_t)r * n;
                                const float *tr = tmp + r * NR;
                                if (first)
                                    for (int jj = 0; jj < nr; jj++) cr[jj] = tr[jj];
                                else
                                    for (int jj = 0; jj < nr; jj++) cr[jj] += tr[jj];
                            }
                        }
                    }
                }
            }
        }
    }
}

/* Per-size autotuning state: each candidate is timed on real calls, then the
   fastest is used. Call 0 is a warm-up with candidate 0, which is retimed. */
#define NSLOT 16
typedef struct {
    int n, calls;
    double best[MAXC];
} tune_t;

static tune_t g_tune[NSLOT];
static int g_ntune = 0;

static tune_t *tune_for(int n)
{
    for (int i = 0; i < g_ntune; i++)
        if (g_tune[i].n == n) return &g_tune[i];
    tune_t *e = g_ntune < NSLOT ? &g_tune[g_ntune++] : &g_tune[n % NSLOT];
    e->n = n;
    e->calls = 0;
    for (int c = 0; c < MAXC; c++) e->best[c] = 1e30;
    return e;
}

void matmul(const float *A, const float *B, float *C, int n)
{
    if (n <= 0) return;
    if (!g_ncand) init_cands();

    tune_t *e = tune_for(n);
    int c;
    if (e->calls <= g_ncand) {
        c = e->calls == 0 ? 0 : e->calls - 1;
    } else {
        c = 0;
        for (int i = 1; i < g_ncand; i++)
            if (e->best[i] < e->best[c]) c = i;
    }

    double t0 = omp_get_wtime();
    run(A, B, C, n, &g_cand[c]);
    double dt = omp_get_wtime() - t0;

    if (dt < e->best[c]) e->best[c] = dt;
    e->calls++;
}
